'use strict';

var Float64Array = require( '@stdlib/array/float64' );
var dlasq4 = require( './../lib/' );

var Z = new Float64Array([ 4.0, 0, 2.5, 0, 5.0, 0, 1.5, 0, 7.5, 0, 3.0, 0, 12.0, 0, 0, 0 ]);
var out = new Float64Array( [ 0, 0, -4.0 ] );

var I0 = 0;
var N0 = 3;
var PP = 0; // Ping-pong flag
var N0IN = 3;
var DMIN = 0.125;
var DMIN1 = 0.25;
var DMIN2 = 0.3;
var DN = 0.75;
var DN1 = 0.5;
var DN2 = 0.4;

dlasq4( I0, N0, Z, PP, N0IN, DMIN, DMIN1, DMIN2, DN, DN1, DN2, out );
console.log( out );

// Reset parameters
Z = new Float64Array([ 4.0, 0, 2.5, 0, 5.0, 0, 1.5, 0, 7.5, 0, 3.0, 0, 12.0, 0, 0, 0 ]);

dlasq4.ndarray( I0, N0, Z, 1, 0, PP, N0IN, DMIN, DMIN1, DMIN2, DN, DN1, DN2, out, 1, 0 );
console.log( out );
